// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {IDeploymentBlock} from "./interfaces/decent/IDeploymentBlock.sol";
import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title DeploymentBlockInitializable
 * @author Decent Labs
 * @notice Abstract implementation of deployment block tracking for initializable contracts
 * @dev This abstract contract implements IDeploymentBlock, providing a standard
 * way to record when initializable contracts are deployed.
 *
 * Implementation details:
 * - Uses EIP-7201 namespaced storage pattern for upgradeability
 * - Records block number during initialization
 * - Deployment block is immutable once set
 * - Designed for UUPS and transparent proxy patterns
 * - Must be inherited by initializable contracts
 *
 * Usage:
 * - Call __DeploymentBlockInitializable_init() in the inheriting contract's initializer
 * - The deployment block is automatically set to the current block
 * - Query deploymentBlock() to get the recorded value
 *
 * Security considerations:
 * - Can only be set once during initialization
 * - Prevents reinitialization attacks
 * - Provides reliable deployment block number
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract DeploymentBlockInitializable is
    Initializable,
    IDeploymentBlock
{
    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Main storage struct for DeploymentBlockInitializable following EIP-7201
     * @dev Stores the block number when the contract was deployed
     * @custom:storage-location erc7201:Decent.DeploymentBlockInitializable.main
     */
    struct DeploymentBlockInitializableStorage {
        /** @notice The block number when this contract was deployed */
        uint256 deploymentBlock;
    }

    /**
     * @dev Storage slot for DeploymentBlockInitializableStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.DeploymentBlockInitializable.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION =
        0x8a73f35b9df1b6f9967ddd5a4ec6ec57f8bdee83334d4552823c6e36f981ab00;

    /**
     * @dev Returns the storage struct for DeploymentBlockInitializable
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for DeploymentBlockInitializable
     */
    function _getDeploymentBlockInitializableStorage()
        internal
        pure
        returns (DeploymentBlockInitializableStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := DEPLOYMENT_BLOCK_INITIALIZABLE_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // CONSTRUCTOR & INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the deployment block tracking
     * @dev Must be called by inheriting contracts in their initializer.
     * Records the current block number as the deployment block.
     * Can only be called once due to the check for existing value.
     * @custom:throws DeploymentBlockAlreadySet if already initialized
     */
    function __DeploymentBlockInitializable_init() internal onlyInitializing {
        // solhint-disable-previous-line func-name-mixedcase
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        if ($.deploymentBlock != 0) {
            revert DeploymentBlockAlreadySet();
        }

        $.deploymentBlock = block.number;
    }

    // ======================================================================
    // IDeploymentBlock
    // ======================================================================

    // --- View Functions ---

    /**
     * @inheritdoc IDeploymentBlock
     */
    function deploymentBlock() public view virtual override returns (uint256) {
        DeploymentBlockInitializableStorage
            storage $ = _getDeploymentBlockInitializableStorage();
        return $.deploymentBlock;
    }
}

contracts/InitializerEventEmitter.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

import {
    Initializable
} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title InitializerEventEmitter
 * @author Decent Labs
 * @notice Abstract contract for emitting initialization data during contract deployment
 * @dev This abstract contract provides a standardized way to emit initialization
 * data for initializable contracts in the Decent ecosystem.
 *
 * Implementation details:
 * - Designed to be inherited by upgradeable contracts
 * - Emits raw initialization data for transparency and auditability
 * - Minimal gas overhead with single event emission
 * - Follows OpenZeppelin's initializer pattern
 * - Uses `onlyInitializing` modifier for security
 *
 * Usage:
 * - Inherit this contract in your upgradeable contract
 * - Call `__InitializerEventEmitter_init()` in your initializer function
 * - Pass the encoded initialization parameters as bytes
 *
 * Example:
 * ```solidity
 * contract MyContract is InitializerEventEmitter, OtherContracts {
 *     function initialize(address owner_, uint256 value_) public initializer {
 *         bytes memory initData = abi.encode(owner_, value_);
 *         __InitializerEventEmitter_init(initData);
 *         // ... rest of initialization
 *     }
 * }
 * ```
 *
 * @custom:security-contact security@decentlabs.io
 */
abstract contract InitializerEventEmitter is Initializable {
    // ======================================================================
    // ERRORS
    // ======================================================================

    /**
     * @notice Thrown when attempting to initialize after already initialized
     * @dev Prevents reinitialization attacks on upgradeable contracts
     */
    error InitializeDataAlreadyEmitted();

    // ======================================================================
    // EVENTS
    // ======================================================================

    /**
     * @notice Emitted when a contract is initialized with data
     * @dev This event provides transparency for all initialization parameters
     * @param initData The raw initialization data passed to the contract
     */
    event InitializeData(bytes initData);

    // ======================================================================
    // STATE VARIABLES
    // ======================================================================

    /**
     * @notice Storage struct for InitializerEventEmitter following EIP-7201
     * @dev Tracks whether initialization data has been emitted
     * @custom:storage-location erc7201:Decent.InitializerEventEmitter.main
     */
    struct InitializerEventEmitterStorage {
        /** @notice Whether the initialization data has been emitted */
        bool initialized;
    }

    /**
     * @dev Storage slot for InitializerEventEmitterStorage calculated using EIP-7201 formula:
     * keccak256(abi.encode(uint256(keccak256("Decent.InitializerEventEmitter.main")) - 1)) & ~bytes32(uint256(0xff))
     */
    bytes32 internal constant INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION =
        0xf7464a9b8e299d18ec8976df251e878e5204887b642c36b9e3e606b459323300;

    /**
     * @dev Returns the storage struct for InitializerEventEmitter
     * Following the EIP-7201 namespaced storage pattern to avoid storage collisions
     * @return $ The storage struct for InitializerEventEmitter
     */
    function _getInitializerEventEmitterStorage()
        internal
        pure
        returns (InitializerEventEmitterStorage storage $)
    {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := INITIALIZER_EVENT_EMITTER_STORAGE_LOCATION
        }
    }

    // ======================================================================
    // INITIALIZERS
    // ======================================================================

    /**
     * @notice Initializes the event emitter and emits the initialization data
     * @dev Must be called by inheriting contracts in their initializer function.
     * Can only be called once - subsequent calls will revert.
     * @param initData The initialization data to emit
     * @custom:throws InitializeDataAlreadyEmitted if already initialized
     */
    function __InitializerEventEmitter_init(
        // solhint-disable-previous-line func-name-mixedcase
        bytes memory initData
    ) internal onlyInitializing {
        InitializerEventEmitterStorage
            storage $ = _getInitializerEventEmitterStorage();

        if ($.initialized) {
            revert InitializeDataAlreadyEmitted();
        }

        $.initialized = true;
        emit InitializeData(initData);
    }
}

contracts/interfaces/decent/deployables/.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IVersion
 * @notice Simple interface for contract versioning
 * @dev This interface provides a standard way for contracts to expose their version
 * number. Used throughout the Decent Protocol to track contract versions for
 * upgrades, compatibility checks, and off-chain tooling.
 *
 * Version numbers are uint16 values, typically starting at 1 and incrementing
 * with each major contract revision. This allows:
 * - Upgrade tooling to verify compatibility
 * - Frontend applications to adapt to different versions
 * - Analytics to track deployment versions
 */
interface IVersion {
    // --- Pure Functions ---

    /**
     * @notice Returns the contract's version number
     * @dev Pure function that returns a hardcoded version. Typically returns 1
     * for V1 contracts, 2 for V2, etc.
     * @return version The contract version as a uint16
     */
    function version() external pure returns (uint16 version);
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IVotesERC20V1
 * @notice Governance token with voting capabilities and transfer restrictions
 * @dev This interface defines a flexible governance token that extends ERC20 with voting
 * delegation features and optional transfer restrictions. It supports snapshots for
 * historical voting power queries and can be configured as non-transferable.
 *
 * Key features:
 * - ERC20Votes compatibility for governance systems
 * - Optional transfer locking (non-transferable tokens)
 * - Maximum supply cap enforcement
 * - Role-based transfer overrides when locked
 * - Timestamp-based voting snapshots
 * - Minting controlled by role
 *
 * Usage:
 * - Primary governance token for DAOs
 * - Voting weight in Azorius proposals
 * - Can be locked to prevent token transfers
 * - Supports delegation for liquid democracy
 */
interface IVotesERC20V1 {
    // --- Errors ---

    /** @notice Thrown when attempting transfers on a locked (non-transferable) token */
    error IsLocked();

    /** @notice Thrown when locking token from unlocked state */
    error LockFromUnlockedState();

    /** @notice Thrown when minting is disabled */
    error MintingDisabled();

    /** @notice Thrown when minting would exceed the maximum total supply */
    error ExceedMaxTotalSupply();

    /** @notice Thrown when setting max supply below current total supply */
    error InvalidMaxTotalSupply();

    // --- Events ---

    /**
     * @notice Emitted when the token's transfer lock status changes
     * @param isLocked True if transfers are now locked, false if unlocked
     */
    event Locked(bool isLocked);

    /**
     * @notice Emitted when the token's minting is renounced
     */
    event MintingRenounced();

    /**
     * @notice Emitted when the maximum total supply is updated
     * @param newMaxTotalSupply The new maximum supply cap
     */
    event MaxTotalSupplyUpdated(uint256 newMaxTotalSupply);

    // --- Structs ---

    /**
     * @notice Token metadata
     * @param name The token name (e.g., "MyDAO Governance Token")
     * @param symbol The token symbol (e.g., "MYDAO")
     */
    struct Metadata {
        string name;
        string symbol;
    }

    /**
     * @notice Initial token allocation
     * @param to Recipient address
     * @param amount Number of tokens to allocate
     */
    struct Allocation {
        address to;
        uint256 amount;
    }

    // --- Initializer Functions ---

    /**
     * @notice Initializes the governance token with initial allocations
     * @dev Can only be called once during deployment. Sets up the token with
     * initial distribution and configuration. Decimals are fixed at 18.
     * @param metadata_ Token name and symbol
     * @param allocations_ Initial token distributions
     * @param owner_ Address that will have admin and minter roles
     * @param locked_ Whether the token should be non-transferable
     * @param maxTotalSupply_ Maximum supply cap
     */
    function initialize(
        Metadata calldata metadata_,
        Allocation[] calldata allocations_,
        address owner_,
        bool locked_,
        uint256 maxTotalSupply_
    ) external;

    // --- Pure Functions ---

    /**
     * @notice Returns the clock mode for voting snapshots
     * @dev Returns "mode=timestamp" indicating timestamp-based timing
     * @return clockMode The clock mode string per EIP-6372
     */
    function CLOCK_MODE() external pure returns (string memory clockMode);
    // solhint-disable-previous-line func-name-mixedcase

    // --- View Functions ---

    /**
     * @notice Returns the current clock value (timestamp)
     * @dev Used for voting snapshot timing, returns current block timestamp
     * @return clock The current timestamp as uint48
     */
    function clock() external view returns (uint48 clock);

    /**
     * @notice Returns whether the token is locked (non-transferable)
     * @dev When locked, only addresses with special roles can transfer
     * @return isLocked True if transfers are restricted
     */
    function locked() external view returns (bool isLocked);

    /**
     * @notice Returns whether minting is disabled
     * @dev When disabled, no new tokens can be minted
     * @return isMintingRenounced True if minting is disabled
     */
    function mintingRenounced() external view returns (bool isMintingRenounced);

    /**
     * @notice Returns the maximum total supply cap
     * @return maxTotalSupply The maximum number of tokens that can exist
     */
    function maxTotalSupply() external view returns (uint256 maxTotalSupply);

    /**
     * @notice Returns when the token was last unlocked
     * @dev Returns the timestamp of the most recent unlock operation.
     * Updated whenever lock(false) is called. Returns 0 if never unlocked.
     * @return unlockTime The timestamp when the token was last unlocked
     */
    function getUnlockTime() external view returns (uint48 unlockTime);

    // --- State-Changing Functions ---

    /**
     * @notice Updates the token's transfer lock status
     * @dev Only callable by admin. When unlocking, records the timestamp in unlockTime.
     * @param locked_ True to lock transfers, false to unlock
     * @custom:access Restricted to admin role
     * @custom:emits Locked
     */
    function lock(bool locked_) external;

    /**
     * @notice Renounces the ability to mint new tokens
     * @dev Only callable by admin. Once called, minting is permanently disabled.
     * @custom:access Restricted to admin role
     * @custom:emits MintingDisabled
     */
    function renounceMinting() external;

    /**
     * @notice Updates the maximum total supply cap
     * @dev Only callable by admin. Cannot set below current total supply.
     * @param newMaxTotalSupply_ The new maximum supply
     * @custom:access Restricted to admin role
     * @custom:throws InvalidMaxTotalSupply if below current supply
     * @custom:emits MaxTotalSupplyUpdated
     */
    function setMaxTotalSupply(uint256 newMaxTotalSupply_) external;

    /**
     * @notice Mints new tokens to a specified address
     * @dev Only callable by addresses with MINTER_ROLE. Respects max supply.
     * @param to_ The address to receive tokens
     * @param amount_ The number of tokens to mint
     * @custom:access Restricted to minter role
     * @custom:throws ExceedMaxTotalSupply if would exceed cap
     */
    function mint(address to_, uint256 amount_) external;

    /**
     * @notice Burns tokens from the caller's balance
     * @dev Anyone can burn their own tokens. No access control.
     * Works even when the token is locked.
     * @param amount_ The number of tokens to burn
     */
    function burn(uint256 amount_) external;
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IWarrantBase
 * @notice Base interface for warrant contracts that allow holders to execute and receive vested tokens
 * @dev This interface defines the core functionality for warrant contracts. A warrant allows
 * a designated holder to pay a fee to receive tokens that will be vested according to
 * implementation-specific rules.
 *
 * Key features:
 * - Single warrant holder with exclusive execution rights
 * - Fee payment in specified token at predetermined price
 * - Support for both absolute and relative time expiration
 * - Owner clawback after expiration if not executed
 *
 * Implementations should handle the actual vesting mechanism (e.g., Hedgey, Sablier)
 * while this base interface provides common warrant functionality.
 */
interface IWarrantBase {
    // --- Errors ---

    /** @notice Thrown when caller is not the designated warrant holder */
    error OnlyWarrantHolder();

    /** @notice Thrown when warrant has already been executed */
    error AlreadyExecuted();

    /** @notice Thrown when warrant has expired and cannot be executed */
    error WarrantExpired();

    /** @notice Thrown when attempting clawback before warrant expiration */
    error WarrantNotExpired();

    /** @notice Thrown when token is still locked (relative time mode only) */
    error TokenLocked();

    /** @notice Thrown when token doesn't support IVotesERC20V1 in relative time mode */
    error UnsupportedToken();

    // --- Events ---

    /**
     * @notice Emitted when warrant is successfully executed
     * @param recipient Address that will receive the vested tokens
     */
    event Executed(address indexed recipient);

    /**
     * @notice Emitted when owner claws back tokens after expiration
     * @param recipient Address that received the clawed back tokens
     * @param amount Amount of tokens clawed back
     */
    event Clawback(address indexed recipient, uint256 amount);

    // --- View Functions ---

    /**
     * @notice Whether the warrant uses relative time based on token unlock
     * @return True if relative time mode, false if absolute time mode
     */
    function relativeTime() external view returns (bool);

    /**
     * @notice The address authorized to execute this warrant
     * @return Address of the warrant holder
     */
    function warrantHolder() external view returns (address);

    /**
     * @notice The token that will be vested upon execution
     * @return Address of the warrant token contract
     */
    function warrantToken() external view returns (address);

    /**
     * @notice The token used for payment
     * @return Address of the payment token contract
     */
    function paymentToken() external view returns (address);

    /**
     * @notice Amount of warrant tokens to be vested
     * @return The warrant token amount
     */
    function warrantTokenAmount() external view returns (uint256);

    /**
     * @notice Price per warrant token in payment token units (18 decimal precision)
     * @return The warrant token price
     */
    function warrantTokenPrice() external view returns (uint256);

    /**
     * @notice Address that receives payment
     * @return The payment receiver address
     */
    function paymentReceiver() external view returns (address);

    /**
     * @notice Expiration timestamp or duration based on time mode
     * @return For absolute time: timestamp when warrant expires
     *         For relative time: duration after token unlock when warrant expires
     */
    function expiration() external view returns (uint256);

    /**
     * @notice Whether the warrant has been executed
     * @return True if executed, false otherwise
     */
    function executed() external view returns (bool);

    // --- State-Changing Functions ---

    /**
     * @notice Execute the warrant by paying the fee and initiating token vesting
     * @dev Only callable by warrant holder before expiration
     * @param recipient_ Address that will receive the vested tokens
     * @custom:throws OnlyWarrantHolder if caller is not the warrant holder
     * @custom:throws AddressZero if recipient is zero address
     * @custom:throws AlreadyExecuted if warrant was already executed
     * @custom:throws Expired if warrant has expired
     * @custom:throws TokenLocked if in relative time mode and token is still locked
     */
    function execute(address recipient_) external;

    /**
     * @notice Owner claws back tokens after warrant expiration
     * @dev Only callable by owner after warrant has expired without execution
     * @param recipient_ Address to receive the clawed back tokens
     * @custom:throws AlreadyExecuted if warrant was already executed
     * @custom:throws WarrantNotExpired if warrant hasn't expired yet
     * @custom:throws TokenLocked if in relative time mode and token is still locked
     */
    function clawback(address recipient_) external;
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IWarrantHedgeyV1
 * @notice Interface for Hedgey-specific warrant implementation
 * @dev This interface defines the Hedgey TokenLockupPlans integration for warrant contracts.
 * The implementation creates a vesting plan through Hedgey when the warrant is executed.
 *
 * Hedgey vesting parameters:
 * - Start time: When vesting begins (absolute or relative to token unlock)
 * - Cliff: Period before any tokens can be claimed
 * - Rate: Amount of tokens vested per period
 * - Period: Time interval for vesting (e.g., daily, monthly)
 *
 * The warrant holder pays a fee to execute and create a Hedgey vesting plan
 * for the recipient address.
 */
interface IWarrantHedgeyV1 {
    // --- Errors ---

    /** @notice Thrown when attempting to execute before hedgeyStart in absolute time mode */
    error HedgeyStartNotElapsed();

    /** @notice Thrown when amount is zero */
    error InvalidAmount();

    /** @notice Thrown when vesting rate is zero */
    error InvalidRate();

    /** @notice Thrown when rate exceeds total amount */
    error RateExceedsAmount();

    /** @notice Thrown when vesting period is zero */
    error InvalidPeriod();

    /** @notice Thrown when token is zero address */
    error InvalidToken();

    /** @notice Thrown when cliff exceeds vesting end time */
    error CliffExceedsEnd(uint256 cliff, uint256 end);

    // --- Structs ---

    /**
     * @notice Parameters for initializing a Hedgey warrant
     * @param relativeTime Whether to use relative time based on token unlock
     * @param owner Owner address who can clawback after expiration
     * @param warrantHolder Address authorized to execute the warrant
     * @param warrantToken Token to be vested
     * @param paymentToken Token used for payment
     * @param warrantTokenAmount Amount of warrant tokens to vest
     * @param warrantTokenPrice Price per warrant token in payment token units (18 decimals)
     * @param paymentReceiver Address that receives payment
     * @param expiration Expiration timestamp or duration
     * @param hedgeyTokenLockupPlans Hedgey contract address
     * @param hedgeyStart Vesting start time (absolute or relative)
     * @param hedgeyRelativeCliff Cliff duration from start
     * @param hedgeyRate Tokens vested per period
     * @param hedgeyPeriod Vesting period duration
     */
    struct InitParams {
        bool relativeTime;
        address owner;
        address warrantHolder;
        address warrantToken;
        address paymentToken;
        uint256 warrantTokenAmount;
        uint256 warrantTokenPrice;
        address paymentReceiver;
        uint256 expiration;
        address hedgeyTokenLockupPlans;
        uint256 hedgeyStart;
        uint256 hedgeyRelativeCliff;
        uint256 hedgeyRate;
        uint256 hedgeyPeriod;
    }

    // --- Events ---

    /**
     * @notice Emitted when a Hedgey vesting plan is created
     * @param planId The ID of the created vesting plan
     * @param recipient The address that will receive the vested tokens
     */
    event HedgeyPlanCreated(uint256 indexed planId, address indexed recipient);

    // --- Initializer Functions ---

    /**
     * @notice Initialize the warrant with Hedgey-specific parameters
     * @param params_ Struct containing all initialization parameters
     */
    function initialize(InitParams calldata params_) external;

    // --- View Functions ---

    /**
     * @notice Address of the Hedgey TokenLockupPlans contract
     * @return The Hedgey contract address for creating vesting plans
     */
    function hedgeyTokenLockupPlans() external view returns (address);

    /**
     * @notice Start time for Hedgey vesting plan
     * @return For absolute time: timestamp when vesting starts
     *         For relative time: offset from token unlock time
     */
    function hedgeyStart() external view returns (uint256);

    /**
     * @notice Cliff duration before tokens can be claimed
     * @return Duration in seconds from hedgeyStart
     */
    function hedgeyRelativeCliff() external view returns (uint256);

    /**
     * @notice Amount of tokens vested per period
     * @return Token amount vested each period
     */
    function hedgeyRate() external view returns (uint256);

    /**
     * @notice Time interval for vesting
     * @return Period duration in seconds
     */
    function hedgeyPeriod() external view returns (uint256);
}

